+import { parameters as P } from './parameters.mjs';
+export const E=P.coordinateTolerance;
+export const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
+export const distance=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
