+    }
+    if(!found) {
+      const collinear=p.findIndex((b,i)=>Math.abs(cross(p[(i+p.length-1)%p.length],b,p[(i+1)%p.length]))<=E*E);
+      if(collinear<0)throw Error('Cannot triangulate simple polygon');p.splice(collinear,1);
+    }
+  }
