+}
+function clippedArea(subject,clip) {
+  let out=subject;
+  for(const [a,b] of edges(clip)) {
+    const input=out;out=[];
+    for(let i=0;i<input.length;i++) {
+      const c=input[i],d=input[(i+1)%input.length],v=cross(a,b,c),w=cross(a,b,d);
+      if(v>=0)out.push(c);
