+}
+export function coastMidpoint(p,board,destination) {
+  const own=board.islands.find(i=>i.id===p.island),ob=box(own.polygon),db=box(destination.polygon);
+  const direction=[(db[0]+db[2]-ob[0]-ob[2])/2,(db[1]+db[3]-ob[1]-ob[3])/2];
