+    const len=Math.hypot(b[0]-a[0],b[1]-a[1]);
+    if(half<=len)return [a[0]+(b[0]-a[0])*half/len,a[1]+(b[1]-a[1])*half/len];
+    half-=len;
+  }
+}
+function waterPath(start,end,islands) {
+  const rectangles=islands.map(i=>[...i.polygon[0],...i.polygon[2]]);
