+ attachment:[
+  ['wrong country',b=>{const r=b.routes[0];r.points[0]=country(b,r.to).polygon[0];}],
+  ['interior endpoint',b=>{const r=b.routes[0];r.points[0]=country(b,r.from).labelAt;}],
