+        }
+      }
+    }
+    if(name==='bonus')for(const i of board.islands){const expected=Math.max(2,Math.floor(i.provinces.length/2)+entrances.get(i.id));if(i.bonus!==expected||i.bonus>i.provinces.length)fail(`Invalid bonus ${i.id}`);}
