+    if(distance(a,b)<=E||Math.abs(cross(a,b,c))/distance(a,b)>E)return [];
+    return [along(c,a,b),along(d,a,b)].filter(t=>t>=0&&t<=1);
+  }
+  const t=((c[0]-a[0])*sy-(c[1]-a[1])*sx)/denom;
