cat > tests/core/_tmp-edges.test.ts << 'EOF'
import {describe,it} from 'vitest';
import {readFileSync} from 'fs';
const witness=JSON.parse(readFileSync('docs/prototypes/new-game/T34/witness.json','utf8'));
describe('witness',()=>{
  it('shared edges check',()=>{
    const shared=new Set<string>();
    for(let i=0;i<witness.provinces.length;i++){
      for(let j=i+1;j<witness.provinces.length;j++){
        const a=witness.provinces[i];
        const b=witness.provinces[j];
        if(a.island!==b.island)continue;
        const aSet=new Set(a.polygon.map((p:number[])=>p.join(',')));
        const bSet=new Set(b.polygon.map((p:number[])=>p.join(',')));
        const sharedVerts=[...aSet].filter(p=>bSet.has(p));
        if(sharedVerts.length>=2){
          shared.add(a.id+'-'+b.id);
        }
      }
    }
    console.log('vertex-sharing province pairs:',shared.size);
    // Now check which of these have shared edges
    let edgeShare=0;
    for(const pair of shared){
      const [aId,bId]=pair.split('-');
      const a=witness.provinces.find((p:any)=>p.id===aId);
      const b=witness.provinces.find((p:any)=>p.id===bId);
      const aSet=new Set(a.polygon.map((p:number[])=>p.join(',')));
      const bSet=new Set(b.polygon.map((p:number[])=>p.join(',')));
      const sharedVerts=[...aSet].filter(p=>bSet.has(p));
      if(sharedVerts.length>=2){
        // Check if these shared vertices are adjacent on the polygon
        const adjShared=a.polygon.some((p:number[],i:number)=>{
          const next=a.polygon[(i+1)%a.polygon.length];
          return bSet.has(p.join(',')) && bSet.has(next.join(','));
        });
        if(adjShared)edgeShare++;
      }
    }
    console.log('edge-sharing province pairs:',edgeShare);
  });
});
EOF
