import {generateIslandGeography} from '../../src/core/island-geography';
import {createHash} from 'crypto';
import {describe,it} from 'vitest';
import type {IslandGeography} from '../../src/core/island-geography';

function topologyHash(g:IslandGeography):string{
  return createHash('sha256').update(JSON.stringify(g.provinces.map(p=>[p.id,p.borders]))).digest('hex');
}

describe('topology distribution',()=>{
  it('count over 100 seeds',()=>{
    const counts=new Map<string,number>();
    for(let seed=0;seed<100;seed++){
      const r=generateIslandGeography(seed);
      if(!r.ok)continue;
      const h=topologyHash(r.geography);
      counts.set(h,(counts.get(h)??0)+1);
    }
    console.log('Topologies:',counts.size);
    const sorted=[...counts.entries()].sort((a,b)=>b[1]-a[1]);
    for(const [hash,count] of sorted){
      console.log(`  ${hash.slice(0,16)}: ${count} seeds`);
    }
  });
});
EOF
