describe('check shared closing edges',()=>{
  it('check',()=>{
    const shared=(poly1:any, poly2:any):[boolean,number,number]=>{
      for(let i=0;i<poly1.length;i++){
        const a=poly1[i];
        const b=poly1[(i+1)%poly1.length];
        for(let j=0;j<poly2.length;j++){
          const c=poly2[j];
          const d=poly2[(j+1)%poly2.length];
          const cross=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
          const cross2=(b[0]-a[0])*(d[1]-a[1])-(b[1]-a[1])*(d[0]-a[0]);
          if(cross!==0||cross2!==0)continue;
          const axis=Math.abs(b[0]-a[0])>=Math.abs(b[1]-a[1])?0:1;
          const min1=Math.min(a[axis],b[axis]);
          const max1=Math.max(a[axis],b[axis]);
          const min2=Math.min(c[axis],d[axis]);
          const max2=Math.max(c[axis],d[axis]);
          if(Math.min(max1,max2)>Math.max(min1,min2))return [true,i,j];
        }
      }
