import {describe,it} from 'vitest';
import {readFileSync} from 'fs';
const witness=JSON.parse(readFileSync('docs/prototypes/new-game/T34/witness.json','utf8'));

function locate(p:number[], ring:number[][]):number{
  let winding=0;
  for(let i=0;i<ring.length;i++){
    const a=ring[i];
    const b=ring[(i+1)%ring.length];
    const onSegment=(p:number[],a:number[],b:number[]):boolean=>{
      const cross=(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0]);
      if(cross!==0)return false;
      const dot=(b[0]-a[0])*(p[0]-a[0])+(b[1]-a[1])*(p[1]-a[1]);
      const len=(b[0]-a[0])**2+(b[1]-a[1])**2;
      return dot>=0&&dot<=len;
    };
    if(onSegment(p,a,b))return 0;
    if(a[1]<=p[1]&&b[1]>p[1]){
      const cross=(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0]);
      if(cross>0)winding++;
    } else if(a[1]>p[1]&&b[1]<=p[1]){
      const cross=(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0]);
      if(cross<0)winding--;
    }
  }
  return winding===0?-1:1;
}

describe('closing edge of province_4',()=>{
  it('check coast',()=>{
    const p4=witness.provinces.find((p:any)=>p.id==='province_4');
    const N=p4.polygon.length;
    const a=p4.polygon[N-1];
    const b=p4.polygon[0];
    const island_4=witness.islands.find((i:any)=>i.id==='island_4');

    // Check if midpoint of closing edge is on island_4 boundary
    const midX=(a[0]+b[0])/2;
    const midY=(a[1]+b[1])/2;
    console.log('midpoint:',midX,midY);
    console.log('on island boundary:',locate([midX,midY],island_4.polygon));

    // Check if midpoint is inside any other province on island_4
    let insideOther=false;
    for(const q of witness.provinces){
      if(q.id===p4.id||q.island!==p4.island)continue;
      const loc=locate([midX,midY],q.polygon);
      if(loc>=0){
        console.log('inside other province:',q.id);
        insideOther=true;
      }
    }
    if(!insideOther)console.log('midpoint is on coast');
  });
});
EOF
