const witness=JSON.parse(readFileSync('docs/prototypes/new-game/T34/witness.json','utf8'));

describe('check all closing edges',()=>{
  it('check',()=>{
    let coastCount=0;
    let interiorCount=0;
    let otherCount=0;

    for(const p of witness.provinces){
      const island=witness.islands.find((i:any)=>i.id===p.island);
      const N=p.polygon.length;
      const a=p.polygon[N-1];
      const b=p.polygon[0];
      const midX=(a[0]+b[0])/2;
      const midY=(a[1]+b[1])/2;
      const loc=location([midX,midY],island.polygon);

      // Check if shared with another province
      let sharedWithProvince=false;
      for(const q of witness.provinces){
        if(q.id===p.id||q.island!==p.island)continue;
        for(let i=0;i<q.polygon.length;i++){
          const c=q.polygon[i];
          const d=q.polygon[(i+1)%q.polygon.length];
          const cross=(b[0]-a[0])*(d[1]-a[1])-(b[1]-a[1])*(d[0]-a[0]);
          if(cross!==0)continue;
          const axis=Math.abs(b[0]-a[0])>=Math.abs(b[1]-a[1])?0:1;
          const minA=Math.min(a[axis],b[axis]);
          const maxA=Math.max(a[axis],b[axis]);
          const minC=Math.min(c[axis],d[axis]);
          const maxC=Math.max(c[axis],d[axis]);
          if(Math.min(maxA,maxC)>Math.max(minA,minC)){
            sharedWithProvince=true;
            break;
          }
        }
        if(sharedWithProvince)break;
      }

      if(sharedWithProvince){
        interiorCount++;
        console.log(`${p.id}: closing edge is INTERIOR (shared with another province)`);
      } else if(loc===0||loc>0){
        coastCount++;
      } else {
        otherCount++;
      }
    }
    console.log('coast edges:',coastCount);
    console.log('interior edges (shared):',interiorCount);
    console.log('other (outside island):',otherCount);
  });
});
