import {generateIslandGeography} from '../../src/core/island-geography';
import {readFileSync} from 'fs';
import {describe,it} from 'vitest';
import {createHash} from 'crypto';
const witness=JSON.parse(readFileSync('docs/prototypes/new-game/T34/witness.json','utf8'));

describe('borders detailed check',()=>{
  it('check',()=>{
    // Compute witness borders using the implementation's shared function
    const shared=(poly1:any, poly2:any):boolean=>{
      for(let i=0;i<poly1.length;i++){
        const a=poly1[i];
        const b=poly1[(i+1)%poly1.length];
        for(let j=0;j<poly2.length;j++){
          const c=poly2[j];
          const d=poly2[(j+1)%poly2.length];
          const cross=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
          const cross2=(b[0]-a[0])*(d[1]-a[1])-(b[1]-a[1])*(d[0]-a[0]);
          if(cross!==0||cross2!==0)continue;
          const axis=Math.abs(b[0]-a[0])>=Math.abs(b[1]-a[1])?0:1;
          const min1=Math.min(a[axis],b[axis]);
          const max1=Math.max(a[axis],b[axis]);
          const min2=Math.min(c[axis],d[axis]);
          const max2=Math.max(c[axis],d[axis]);
          if(Math.min(max1,max2)>Math.max(min1,min2))return true;
        }
      }
      return false;
    };

    // Compute witness borders (using the actual algorithm in the implementation)
    const witnessBorders=new Map<string,string[]>();
    for(const p of witness.provinces){
      const borders:string[]=[];
      for(const q of witness.provinces){
        if(p.id===q.id||p.island!==q.island)continue;
        if(shared(p.polygon,q.polygon))borders.push(q.id);
      }
      witnessBorders.set(p.id,borders.sort());
    }

    // Now use the warp's "drop closing edge" interpretation and check
    const sharedAfterDrop=(poly1:any, poly2:any):boolean=>{
      // Drop the last edge of poly1 and poly2
      const poly1Cut=poly1.slice(0,-1);
      const poly2Cut=poly2.slice(0,-1);
      return shared(poly1Cut,poly2Cut) || shared(poly1Cut,poly2) || shared(poly1,poly2Cut);
    };

    const witnessBordersDropLast=new Map<string,string[]>();
    for(const p of witness.provinces){
      const borders:string[]=[];
      for(const q of witness.provinces){
        if(p.id===q.id||p.island!==q.island)continue;
        if(sharedAfterDrop(p.polygon,q.polygon))borders.push(q.id);
      }
      witnessBordersDropLast.set(p.id,borders.sort());
    }

    // Compare
    let mismatches=0;
    for(const [id,borders] of witnessBorders){
      const dropped=witnessBordersDropLast.get(id);
      if(JSON.stringify(borders)!==JSON.stringify(dropped)){
        console.log(`mismatch ${id}: orig=${borders}, dropped=${dropped}`);
        mismatches++;
      }
    }
    console.log('mismatches between full and dropped:',mismatches);
  });
});
