import {generateIslandGeography} from '../../src/core/island-geography';
import {readFileSync} from 'fs';
import {describe,it,expect} from 'vitest';
const witness=JSON.parse(readFileSync('docs/prototypes/new-game/T34/witness.json','utf8'));

describe('borders exact',()=>{
  it('check',()=>{
    const r=generateIslandGeography(0);
    expect(r.ok).toBe(true);
    if(r.ok){
      let mismatches=0;
      for(const p of r.geography.provinces){
        const witnessProvince=witness.provinces.find((wp:any)=>wp.id===p.id)!;
        // Compute witness borders via the same algorithm (with modular closing)
        const witnessBorders:string[]=[];
        for(const q of witness.provinces){
          if(q.id===p.id||q.island!==p.island)continue;
          // Check shared edges
          let shared=false;
          for(let i=0;i<witnessProvince.polygon.length;i++){
            const a=witnessProvince.polygon[i];
            const b=witnessProvince.polygon[(i+1)%witnessProvince.polygon.length];
            for(let j=0;j<q.polygon.length;j++){
              const c=q.polygon[j];
              const d=q.polygon[(j+1)%q.polygon.length];
              const cross=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
              const cross2=(b[0]-a[0])*(d[1]-a[1])-(b[1]-a[1])*(d[0]-a[0]);
              if(cross!==0||cross2!==0)continue;
              const axis=Math.abs(b[0]-a[0])>=Math.abs(b[1]-a[1])?0:1;
              const min1=Math.min(a[axis],b[axis]);
              const max1=Math.max(a[axis],b[axis]);
              const min2=Math.min(c[axis],d[axis]);
              const max2=Math.max(c[axis],d[axis]);
              if(Math.min(max1,max2)>Math.max(min1,min2)){
                shared=true;
                break;
              }
            }
            if(shared)break;
          }
          if(shared)witnessBorders.push(q.id);
        }
        witnessBorders.sort();
        const resultBorders=[...p.borders].sort();
        if(JSON.stringify(witnessBorders)!==JSON.stringify(resultBorders)){
          console.log(`mismatch ${p.id}: witness=${witnessBorders}, result=${resultBorders}`);
          mismatches++;
        }
      }
      console.log('total mismatches:',mismatches);
      expect(mismatches).toBe(0);
    }
  });
});
