import {readFileSync} from 'fs';
const witness=JSON.parse(readFileSync('docs/prototypes/new-game/T34/witness.json','utf8'));

describe('eligible edges',()=>{
  it('check',()=>{
    // An eligible T1 site requires:
    // - 2 countries sharing the edge
    // - Each endpoint has 3 owners (one extra for each)
    // - New countries (r, s) have borders < 4 or borders+lanes < 5

    const sharedEdges:any[]=[];

    // Build owners map
    const owners=new Map<string,string[]>();
    const allEdges=new Map<string,{a:any,b:any,ids:string[]}>(); 
    for(const p of witness.provinces){
      for(let i=0;i<p.polygon.length;i++){
        const a=p.polygon[i];
        const b=p.polygon[(i+1)%p.polygon.length];
        const keyA=a.join(',');
        owners.set(keyA,[...(owners.get(keyA)??[]),p.id]);
        const sortedKey=[keyA,b.join(',')].sort().join('|');
        if(!allEdges.has(sortedKey))allEdges.set(sortedKey,{a,b,ids:[]});
        allEdges.get(sortedKey)!.ids.push(p.id);
      }
    }

    // Find eligible edges
    let eligibleCount=0;
    for(const [key,edge] of allEdges){
      const {a,b,ids}=edge;
      if(ids.length!==2)continue;
      const ownersA=owners.get(a.join(','))!;
      const ownersB=owners.get(b.join(','))!;
      if(ownersA.length!==3||ownersB.length!==3)continue;
      const r=ownersA.find(id=>!ids.includes(id))!;
      const s=ownersB.find(id=>!ids.includes(id))!;
      if(r===s)continue;
      // Check if r and s have < 4 borders (before flip)
      const rProvince=witness.provinces.find((p:any)=>p.id===r)!;
      const sProvince=witness.provinces.find((p:any)=>p.id===s)!;
      const rBorders=rProvince.borders?.length??0;
      const sBorders=sProvince.borders?.length??0;
      // Witness doesn't have computed borders (only in partial geography)
      // But borders come from shared edges, which we can compute
      // For now, count rough
      if(rBorders<4&&sBorders<4){
        eligibleCount++;
        console.log(`eligible edge ${a}-${b}: countries=${ids}, r=${r}, s=${s}`);
      }
    }
    console.log('Total eligible edges:',eligibleCount);
  });
});
EOF
