import {describe,it} from 'vitest';
import {readFileSync} from 'fs';
const witness=JSON.parse(readFileSync('docs/prototypes/new-game/T34/witness.json','utf8'));

const shared=(poly1:any, poly2:any):boolean=>{
  for(let i=0;i<poly1.length;i++){
    const a=poly1[i];
    const b=poly1[(i+1)%poly1.length];
    for(let j=0;j<poly2.length;j++){
      const c=poly2[j];
      const d=poly2[(j+1)%poly2.length];
      const cross=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
      const cross2=(b[0]-a[0])*(d[1]-a[1])-(b[1]-a[1])*(d[0]-a[0]);
      if(cross!==0||cross2!==0)continue;
      const axis=Math.abs(b[0]-a[0])>=Math.abs(b[1]-a[1])?0:1;
      const min1=Math.min(a[axis],b[axis]);
      const max1=Math.max(a[axis],b[axis]);
      const min2=Math.min(c[axis],d[axis]);
      const max2=Math.max(c[axis],d[axis]);
      if(Math.min(max1,max2)>Math.max(min1,min2))return true;
    }
  }
  return false;
};

const borders=new Map<string,string[]>();
for(const p of witness.provinces){
  const list:string[]=[];
  for(const q of witness.provinces){
    if(q.id===p.id||q.island!==p.island)continue;
    if(shared(p.polygon,q.polygon))list.push(q.id);
  }
  borders.set(p.id,list);
}

const lanes=new Map<string,number>();
for(const r of witness.entranceReservations){
  lanes.set(r.from,(lanes.get(r.from)??0)+1);
  lanes.set(r.to,(lanes.get(r.to)??0)+1);
}

describe('all eligible edges',()=>{
  it('count',()=>{
    const owners=new Map<string,string[]>();
    const allEdges=new Map<string,{a:any,b:any,ids:string[]}>(); 
    for(const p of witness.provinces){
      for(let i=0;i<p.polygon.length;i++){
        const a=p.polygon[i];
        const b=p.polygon[(i+1)%p.polygon.length];
        const keyA=a.join(',');
        owners.set(keyA,[...(owners.get(keyA)??[]),p.id]);
        const sortedKey=[keyA,b.join(',')].sort().join('|');
        if(!allEdges.has(sortedKey))allEdges.set(sortedKey,{a,b,ids:[]});
        allEdges.get(sortedKey)!.ids.push(p.id);
      }
    }

    let count=0;
    for(const [key,edge] of allEdges){
      const {a,b,ids}=edge;
      if(ids.length!==2)continue;
      const ownersA=owners.get(a.join(','))!;
      const ownersB=owners.get(b.join(','))!;
      if(ownersA.length!==3||ownersB.length!==3)continue;
      const r=ownersA.find(id=>!ids.includes(id))!;
      const s=ownersB.find(id=>!ids.includes(id))!;
      if(r===s)continue;
      const rBorders=borders.get(r)??[];
      const sBorders=borders.get(s)??[];
      const rLanes=lanes.get(r)??0;
      const sLanes=lanes.get(s)??0;
      count++;
      console.log(`edge ${a}-${b}: countries=${ids}, r=${r}(borders=${rBorders.length},lanes=${rLanes}), s=${s}(borders=${sBorders.length},lanes=${sLanes}), eligible=${rBorders.length<4&&rBorders.length+rLanes<5&&sBorders.length<4&&sBorders.length+sLanes<5}`);
    }
    console.log('Total candidate edges:',count);
  });
});
EOF
