cat > tests/core/_tmp-final-check.test.ts << 'EOF'
import {generateIslandGeography} from '../../src/core/island-geography';
import {describe,it,expect} from 'vitest';

describe('final check',()=>{
  it('integer units 1/2048 CSSpx',()=>{
    const r=generateIslandGeography(0);
    expect(r.ok).toBe(true);
    if(r.ok){
      expect(r.geography.unitsPerPixel).toBe(2048);

      // All coordinates must be integers
      let nonIntCount=0;
      for(const p of r.geography.provinces){
        for(const v of p.polygon){
          if(!Number.isSafeInteger(v[0]))nonIntCount++;
          if(!Number.isSafeInteger(v[1]))nonIntCount++;
        }
      }
      expect(nonIntCount).toBe(0);
    }
  });
});
EOF
